ecrire_et_tester_dans_bac_a_sable({'contenu': 'import os
import glob
from email import policy
from email.parser import BytesParser
from email.utils import parsedate_to_datetime
from datetime import datetime

def parser_tous_les_emails_2025():
    mail_base = os.path.expanduser('~/Library/Mail')
    emlx_files = glob.glob(os.path.join(mail_base, '**', '*.emlx'), recursive=True)
    print(f"Total fichiers .emlx trouvés : {len(emlx_files)}")

    limite_date = datetime(2025, 12, 31, 23, 59, 59)
    texte_total = []
    compteur = 0

    for f in emlx_files:
        try:
            with open(f, 'rb') as file:
                msg = BytesParser(policy=policy.default).parse(file)
                date_str = msg.get('Date')
                dt = None
                if date_str:
                    try:
                        dt = parsedate_to_datetime(date_str)
                        if dt and dt.tzinfo:
                            dt = dt.replace(tzinfo=None)
                    except Exception:
                        dt = None

                # Si la date est valide et <= 2025 (ou si date non parsable mais qu'on souhaite tout inclure par sécurité selon la demande)
                if dt is None or dt <= limite_date:
                    sujet = msg.get('Subject', 'Sans sujet')
                    expediteur = msg.get('From', 'Inconnu')

                    corps = ""
                    if msg.is_multipart():
                        for part in msg.walk():
                            if part.get_content_type() == "text/plain":
                                payload = part.get_payload(decode=True)
                                if payload:
                                    corps += payload.decode('utf-8', errors='ignore')
                    else:
                        payload = msg.get_payload(decode=True)
                        if payload:
                            corps = payload.decode('utf-8', errors='ignore')

                    if corps.strip():
                        compteur += 1
                        date_affiche = dt.strftime('%Y-%m-%d %H:%M:%S') if dt else (date_str or 'Inconnue')
                        texte_total.append(f"=== EMAIL {compteur} | DATE: {date_affiche} ===\nDE: {expediteur}\nSUJET: {sujet}\n\nTEXTE INTÉGRAL:\n{corps}\n\n")
        except Exception:
            continue

    print(f"Mails textuels complets extraits jusqu'en 2025 : {compteur}")
    output_path = 'analyse_integrale_texte_brut_2025.txt'
    with open(output_path, 'w', encoding='utf-8') as out:
        out.write("\n".join(texte_total))
    print(f"Rapport final généré: {output_path} ({compteur} messages)")

if __name__ == '__main__':
    parser_tous_les_emails_2025()
', 'commande_validation': 'python extraire_texte_brut_2025_complet.py', 'nom_fichier': 'extraire_texte_brut_2025_complet.py'})

