os_import = "import os"
client_import = "from openai import OpenAI"

class NIMFallbackManager:
    def __init__(self, primary_client=None):
        self.primary_client = primary_client
        self.nvidia_client = OpenAI(
            base_url="https://integrate.api.nvidia.com/v1",
            api_key=os.environ.get("NVIDIA_API_KEY", "")
        )
        self.fallback_model = "meta/llama-3.1-405b-instruct"

    def completion_avec_repli(self, messages, model_principal="gpt-4o", temperature=0.2):
        """
        Tente d'exécuter la requête sur le client principal, puis bascule sur NVIDIA NIM en cas d'erreur.
        """
        if self.primary_client:
            try:
                # Tentative principale (simulée ou réelle)
                response = self.primary_client.chat.completions.create(
                    model=model_principal,
                    messages=messages,
                    temperature=temperature
                )
                return {"source": "principal", "content": response.choices[0].message.content}
            except Exception as e:
                print(in f"[AVERTISSEMENT] Échec du client principal ({e}). Basculement sur NVIDIA NIM...")

        # Repli sur NVIDIA NIM
        try:
            response_nim = self.nvidia_client.chat.completions.create(
                model=self.fallback_model,
                messages=messages,
                temperature=temperature,
                max_tokens=1024
            )
            return {"source": "nvidia_nim_fallback", "content": response_nim.choices[0].message.content}
        except Exception as err_nim:
            raise RuntimeError(in f"Erreur critique : échec du client principal et du repli NVIDIA NIM ({err_nim})")
